Fix $v\in Q$, put $f=f_Q$, $g=f_{Q\setminus\{v\}}$, and write
$h=f/g$, $G=1/h$ at univariate arguments. For $z\in\C$ with
$\operatorname{Im}z>0$,
\begin{equation}\label{poly:pick-inequality}
 \operatorname{Im}h(z)\geq\operatorname{Im}z.
\end{equation}
If $s_j$ are the roots of $g$, with multiplicities, there are
$\nu_j\geq0$ such that
\begin{equation}\label{poly:arrow-quotient}
 h(z)=z+a_v-\sum_j\frac{\nu_j}{z-s_j}.
\end{equation}
Consequently, on choosing $|c_j|^2=\nu_j$,
\begin{equation}\label{poly:arrow-matrix}
 B=\begin{pmatrix}-a_v&c^*\\ c&S\end{pmatrix},
 \qquad S=\diag(s_j),
 \qquad \det(zI-B)=f(z).
\end{equation}
The function $G$ is the transform
\begin{equation}\label{poly:stieltjes}
 G(z)=\int_\R\frac{d\gamma_v(x)}{z-x}
\end{equation}
of the spectral probability measure of $B$ at its first coordinate.
Its first two moments are
\begin{equation}\label{poly:moments}
 \begin{gathered}
 \int x\,d\gamma_v(x)=-a_v,
 \qquad
 \int x^2\,d\gamma_v(x)=a_v^2+\sum_j\nu_j,
 \\
 \sum_j\nu_j=\sum_{w\ne v}|W_{vw}|^2\sum_i t_{vi}t_{wi}.
 \end{gathered}
\end{equation}

Let $N_f(x)$ and $N_g(x)$ count roots strictly greater than $x$, including
multiplicities, and define
\begin{equation}\label{poly:local-functionals}
 \xi_h(x)=N_f(x)-N_g(x),\qquad
 \ell_v=\int_0^\infty\xi_h(x)\,dx,\qquad
 m_v=\int_\R x_+\,d\gamma_v(x).
\end{equation}
Then $\xi_h=\mathbf1_{\{h<0\}}$ off a finite subset of $\R$, and
\begin{equation}\label{poly:poisson}
 \frac{1}{\pi}\arg h(x+i\eta)
   =(P_\eta*\xi_h)(x),
 \qquad P_\eta(x)=\frac{\eta}{\pi(x^2+\eta^2)},\quad\eta>0,
\end{equation}
where $\arg h\in(0,\pi)$. Moreover,
\begin{equation}\label{poly:sum-local-measures}
 \sum_{v\in Q}G_{v,Q}(z)=\frac{f'_Q(z)}{f_Q(z)},
 \qquad
 \sum_{v\in Q}\gamma_v=\sum_{f_Q(\lambda)=0}\delta_\lambda,
\end{equation}
with multiplicities on the right.

If $v$ is made deterministic of color $i$, write $h_i$ for the new quotient
relative to the same $g$, and put $R_i=h_i/h$. Its representation has the same $a_v$ and poles
$s_j$, and masses $\nu_{ij}\geq0$ which can be chosen so that
\begin{equation}\label{poly:pin-average}
 h=\sum_i t_{vi}h_i,\qquad
 \nu_j=\sum_i t_{vi}\nu_{ij}.
\end{equation}
If the penalty at $v$ is also changed to $Ka_v$, the quotient becomes
\begin{equation}\label{poly:buffered-quotient}
 h_i'=h_i+(K-1)a_v.
\end{equation}
Here the prime with a color index denotes the buffered quotient, not a
derivative. We write $\ell'_{v,i}$ for the positive-axis integral of
the spectral shift defined using $h_i'$ and the unchanged $g$.

There is a universal constant $K\geq1$ with the following property.
Suppose $T$, $\mathcal R$, $\mathcal G$, and $\omega$ satisfy the preceding
assumptions. Let $b>0$, and choose a positive integer $r$ such that
\begin{equation}
 2\sqrt{2/r}+2/r<b.
 \label{slab:r-choice}
\end{equation}
For every $\sigma>0$ and $\rho>0$, there is a measurable coloring of $V$
with $r+1$ colors for which
\begin{equation}
 \int_V \bigl((T_{\mathrm{pav}}-(Kb+\sigma)\one)_+^2\bigr)_{vv}
 \,d\mu(v)<\rho.
 \label{slab:measured-conclusion}
\end{equation}

For every $n\geq2$, there are sequences of $n$-partitions in $A$
whose quotient partition $\mathcal P$ satisfies
\begin{equation}\label{exp:off-normalizer-bound}
 \norm{C_{\mathcal P}[Z]}\leq\frac4{\sqrt n}.
\end{equation}

For the finite data above,
\begin{equation}
 P_I(Z)=
 \left(\prod_{v\in I}\frac{1}{k_v!}
                  \partial_{z_v}^{\,k_v-1}\right)
            \prod_j\det\bigl((Z-B_j)|_{U_j}\bigr),
 \qquad \partial_{z_v}P_I=P_{-v}.
 \label{eq:poly-differential}
\end{equation}
More generally, use any matrices \(B_j\) on \(U_j\) in the same
independent-choice construction.  If
\(\operatorname{Im}B_j\leq hI\) for a real number \(h\), then \(P_I(Z)\)
and every deletion polynomial are nonzero whenever
\(\operatorname{Im}z_v>h\) at every remaining site.  In this region,
\begin{equation}
 \operatorname{Im}\frac{P_I(Z)}{P_{-v}(Z|_{I\setminus\{v\}})}
                         \geq\operatorname{Im}z_v-h.
 \label{eq:poly-half-plane}
\end{equation}

Return to the Hermitian data in Equation~\eqref{eq:poly-definition}.
For \(v\in I\), set
\[
 Q_v=P_{-v},\qquad F_v(z)=\frac{P_I(z)}{Q_v(z)},
 \qquad G_v(z)=\frac{Q_v(z)}{P_I(z)}.
\]
These rational functions are analytic in the upper half-plane, and
\begin{equation}
 F_v(z)=z+a_v-\sum_{\lambda}\frac{b_{v,\lambda}}{z-\lambda},
                      \qquad b_{v,\lambda}\geq0,
 \label{eq:poly-arrow-quotient}
\end{equation}
where \(\lambda\) ranges over the distinct roots of \(Q_v\).
Let \(\Lambda_v\) be the diagonal matrix listing those roots with
multiplicity.  There is a vector
\(g_v\), with squared coordinate \(b_{v,\lambda}\) on one copy of each
\(\lambda\) and zero on its other copies, such that
\begin{equation}
                H_v=\begin{pmatrix}-a_v&g_v^*\\ g_v&\Lambda_v\end{pmatrix}
 \label{eq:poly-arrow}
\end{equation}
has characteristic polynomial \(P_I\).  Its first-coordinate spectral
measure \(\rho_v\) is a probability measure satisfying
\begin{equation}
 G_v(z)=\int_{\mathbb R}\frac{1}{z-x}\,\rho_v(dx),\qquad
 \sum_{v\in I}\rho_v=\sum_{P_I(x)=0}\delta_x.
 \label{eq:poly-root-measures}
\end{equation}
The roots on the right are counted with multiplicity, and \(Q_v\)
interlaces \(P_I\).

For a finite zero-diagonal Hermitian contraction \(T\), arbitrary
positive weights, \(r\geq1\), \(t>0\), and a partial coloring as above,
let \(v\) be unassigned.  With \(\beta=80\), there is
\(i\in\{1,\ldots,r\}\) such that
\begin{equation}
                         d_v^{\,i}-d_v\leq24m_v.
 \label{eq:poly-assignment}
\end{equation}
The bound is independent of the finite set and its weights.

Let $(X,\mu,\mathcal R)$, $G$, $\Delta$, and $T$ satisfy the assumptions
above: $\mathcal R$ is countable and nonsingular on a standard probability
space, $G$ is undirected, has no loops, has degree at most $D_0<\infty$, and satisfies
Equation~\eqref{eq:coloring-edge-ratios}, and $T$ is a measurable
Hermitian contraction with zero diagonal and support on $G$, allowing
diagonal unitary conjugacy under a change of root.  Fix an integer $r\geq1$
and a real number $t>3/\sqrt r$, and put $\beta=80$.

For every integer $m\geq1$ and every $\alpha,\eta>0$, there is a measurable
coloring $c:\widetilde X\to\{1,\ldots,r\}$ on the relative Bernoulli
extension such that
\begin{equation}
 \kappa_v\{\omega:c(v,\omega)=i\}=\frac1r
 \quad\text{for every }i\in\{1,\ldots,r\}
 \quad\text{and almost every }v\in X,
 \label{eq:coloring-marginal}
\end{equation}
and
\begin{equation}
 \widetilde\mu\left\{(v,\omega):
       \|T_{B_G(v,m),c}\|\leq2\beta t+\alpha\right\}>1-\eta.
 \label{eq:coloring-ball-conclusion}
\end{equation}

In the model of Lemma~\ref{lem:bernoulli-model}, let $p\in B$ be a
projection such that $\widetilde E_N(p)=\lambda1$, where
$0\le\lambda\le1$. For every $w\in M^\circ$,
\begin{equation}
 \|pwp\|\le(\lambda+2\sqrt\lambda)\|w\|.
 \label{eq:free-compression}
\end{equation}
